mapper.select:

SELECT *
FROM ads_event_overview

WHERE event_id = #{eventId}

SELECT * FROM ads_event_heat_trend
WHERE event_id = #{eventId}
ORDER BY time_bucket ASC

SELECT * FROM ads_platform_spread_timeline
WHERE event_id = #{eventId}
ORDER BY first_publish_time ASC


SELECT *
FROM ads_content_hot_rank

WHERE event_id = #{eventId}

  AND platform <> 'WEIBO'

ORDER BY platform_heat_index DESC, hot_score DESC, publish_time DESC

LIMIT #{limit}

SELECT * FROM ads_platform_daily_heat
WHERE event_id = #{eventId}
ORDER BY time_bucket ASC, platform ASC

SELECT * FROM ads_interaction_summary
WHERE event_id = #{eventId}
ORDER BY hot_score DESC


SELECT *
FROM ads_keyword_rank

WHERE event_id = #{eventId}

ORDER BY word_count DESC

LIMIT #{limit}

SELECT * FROM ads_sentiment_trend
WHERE event_id = #{eventId}
ORDER BY time_bucket ASC, sentiment_label ASC


SELECT content_id, title, clean_text, source_url, platform, publish_time, category,
       hot_score, platform_heat_index, like_count, comment_count, repost_count, favorite_count
FROM ads_content_hot_rank

WHERE event_id = #{eventId}
  AND platform = #{platform}

  AND  = #{category}

  AND publish_time >= #{start}

  AND publish_time < #{end}

ORDER BY publish_time ASC, platform_heat_index DESC, id ASC

LIMIT #{offset}, #{limit}


SELECT COUNT(*)
FROM ads_content_hot_rank

WHERE event_id = #{eventId}
  AND platform = #{platform}

  AND  = #{category}

  AND publish_time >= #{start}

  AND publish_time < #{end}


SELECT *
FROM ads_content_hot_rank

WHERE event_id = #{eventId}

ORDER BY rank_no ASC

LIMIT #{limit}


WITH ranked_contents AS (
    SELECT content.*,

           ROW_NUMBER() OVER (

               PARTITION BY COALESCE(NULLIF(TRIM(category), ''), '综合')
               ORDER BY publish_time DESC, id DESC
           ) AS category_row_no
    FROM ads_content_hot_rank content

    WHERE event_id = #{eventId}
)

SELECT *
FROM ranked_contents

WHERE category_row_no <= #{limit}

ORDER BY publish_time DESC, id DESC

SELECT * FROM ads_content_hot_rank
WHERE event_id = #{eventId}
AND (title LIKE CONCAT('%', #{query}, '%') OR clean_text LIKE CONCAT('%', #{query}, '%') OR author_name LIKE CONCAT('%', #{query}, '%'))
AND platform = #{platform}
AND sentiment_label = #{sentiment}
AND UPPER(TRIM(platform)) NOT IN ('WEIBO', 'SINA_WEIBO')
AND COALESCE(NULLIF(TRIM(category), ''), '综合') =
CASE #{category} WHEN 'finance' THEN '财经' WHEN 'politics' THEN '政治' WHEN 'technology' THEN '科技' WHEN 'sports' THEN '体育' WHEN 'culture' THEN '文娱' WHEN 'society' THEN '社会' ELSE '综合' END
ORDER BY publish_time DESC, id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM ads_content_hot_rank
WHERE event_id = #{eventId}
AND (title LIKE CONCAT('%', #{query}, '%') OR clean_text LIKE CONCAT('%', #{query}, '%') OR author_name LIKE CONCAT('%', #{query}, '%'))
AND platform = #{platform}
AND sentiment_label = #{sentiment}
AND UPPER(TRIM(platform)) NOT IN ('WEIBO', 'SINA_WEIBO')
AND COALESCE(NULLIF(TRIM(category), ''), '综合') =
CASE #{category} WHEN 'finance' THEN '财经' WHEN 'politics' THEN '政治' WHEN 'technology' THEN '科技' WHEN 'sports' THEN '体育' WHEN 'culture' THEN '文娱' WHEN 'society' THEN '社会' ELSE '综合' END

SELECT content_id, title, source_url, platform, publish_time, keywords, category, author_name, like_count, comment_count, repost_count, favorite_count FROM ads_content_hot_rank
WHERE event_id = #{eventId}
AND platform IN ('SOHU_NEWS', 'TENCENT_NEWS', 'NETEASE_NEWS', 'SINA_NEWS', 'THE_PAPER')
AND NULLIF(TRIM(keywords), '') IS NOT NULL
ORDER BY publish_time DESC, id DESC
LIMIT #{limit}

SELECT * FROM ads_noise_summary
WHERE event_id = #{eventId}
ORDER BY time_bucket ASC

SELECT * FROM etl_batch
ORDER BY started_at DESC
LIMIT #{limit}

SELECT * FROM etl_task_log
WHERE batch_id = #{batchId}
ORDER BY started_at ASC
